def possible_sets(n, points):
    from collections import deque
    full = (1<<n) - 1
    seen = set()
    q = deque([full])
    seen.add(full)
    while q:
        mask = q.popleft()
        for k in range(n):
            if (mask & (1<<k)) == 0:
                continue
            xk, yk = points[k]
            newmask = mask
            for i in range(n):
                if (mask & (1<<i)) == 0 or i==k:
                    continue
                xi, yi = points[i]
                if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                    newmask &= ~(1<<i)
            if newmask not in seen:
                seen.add(newmask)
                q.append(newmask)
    return len(seen), seen

