import sys
sys.setrecursionlimit(10000)
MOD = 998244353

def main():
    data = sys.stdin.read().strip().split()
    N = int(data[0])
    M = int(data[1])
    A = [int(x) - 1 for x in data[2:2+N]]
    children = [[] for _ in range(N)]
    for i in range(N):
        children[A[i]].append(i)

    on_cycle = [False] * N
    color = [0] * N  # 0 unvis, 1 on current path, 2 done
    for start in range(N):
        if color[start] != 0:
            continue
        u = start
        while color[u] == 0:
            color[u] = 1
            u = A[u]
        if color[u] == 1:
            v = u
            while True:
                on_cycle[v] = True
                v = A[v]
                if v == u:
                    break
        u = start
        while color[u] == 1:
            color[u] = 2
            u = A[u]

    prefix = [[0] * (M + 1) for _ in range(N)]
    computed = [False] * N

    def compute(v):
        if computed[v] or on_cycle[v]:
            return
        computed[v] = True
        for c in children[v]:
            compute(c)
        p = prefix[v]
        ch = children[v]
        for k in range(1, M + 1):
            prod = 1
            for c in ch:
                prod = prod * prefix[c][k] % MOD
            p[k] = (p[k - 1] + prod) % MOD

    for i in range(N):
        if not on_cycle[i]:
            compute(i)

    answer = 1
    visited_cycle = [False] * N
    for i in range(N):
        if on_cycle[i] and not visited_cycle[i]:
            cycle_nodes = []
            u = i
            while not visited_cycle[u]:
                visited_cycle[u] = True
                cycle_nodes.append(u)
                u = A[u]
            attachments = []
            for cn in cycle_nodes:
                for c in children[cn]:
                    if not on_cycle[c]:
                        attachments.append(c)
            ways = 0
            for k in range(1, M + 1):
                prod = 1
                for a in attachments:
                    prod = prod * prefix[a][k] % MOD
                ways = (ways + prod) % MOD
            answer = answer * ways % MOD
    print(answer)

