import sys
def omega(n):
    cnt = 0
    while n % 2 == 0:
        cnt += 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            cnt += 1
            n //= i
        i += 2
    if n > 1:
        cnt += 1
    return cnt

