import itertools
import functools

def lis_length(perm):
    # O(n^2) or patience
    from bisect import bisect_left
    tails = []
    for x in perm:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def lds_length(perm):
    return lis_length([-x for x in perm])

def check(perm, A, B):
    if lis_length(perm) != A or lds_length(perm) != B:
        return False
    N = len(perm)
    # possible x = k+0.5 for k=0 to N
    for k in range(0, N+1):
        x = k + 0.5
        below = [v for v in perm if v < x]
        above = [v for v in perm if v > x]
        if lis_length(below) <= A-1 and lds_length(above) <= B-1:
            return True
    return False

def count(A, B):
    N = A*B - 1
    cnt = 0
    for p in itertools.permutations(range(1, N+1)):
        if check(p, A, B):
            cnt += 1
    return cnt

