class SegTree:
    def __init__(self, n):
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.mx = [0] * (2 * self.size)
        self.lz = [0] * (2 * self.size)
        self.h = self.size.bit_length() - 1

    def _apply(self, p, val):
        self.mx[p] += val
        self.lz[p] += val

    def _push(self, p):
        if self.lz[p]:
            self._apply(p<<1, self.lz[p])
            self._apply(p<<1|1, self.lz[p])
            self.lz[p] = 0

    def _push_path(self, p):
        for s in range(self.h, 0, -1):
            self._push(p >> s)

    def add(self, l, r, val):  # [l, r) 0-based
        if l >= r:
            return
        l += self.size
        r += self.size
        self._push_path(l)
        self._push_path(r - 1)
        l0, r0 = l, r
        while l < r:
            if l & 1:
                self._apply(l, val)
                l += 1
            if r & 1:
                r -= 1
                self._apply(r, val)
            l >>= 1
            r >>= 1
        self._rebuild(l0)
        self._rebuild(r0 - 1)

    def _rebuild(self, p):
        while p > 1:
            p >>= 1
            self.mx[p] = self.lz[p] + max(self.mx[p<<1], self.mx[p<<1|1])

    def query_max(self):
        return self.mx[1]

