import sys

def min_cost(A, P, B, Q, W):
    if W <= 0:
        return 0
    res = 10**30
    for x in range(B):
        rem = W - A * x
        if rem <= 0:
            cost = P * x
        else:
            y = (rem + B - 1) // B
            cost = P * x + Q * y
        if cost < res:
            res = cost
    for y in range(A):
        rem = W - B * y
        if rem <= 0:
            cost = Q * y
        else:
            x = (rem + A - 1) // A
            cost = P * x + Q * y
        if cost < res:
            res = cost
    return res

def can(W, machines, X):
    total = 0
    for A, P, B, Q in machines:
        total += min_cost(A, P, B, Q, W)
        if total > X:
            return False
    return True

