class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        max_c = L
        ops = [0] * (max_c + 1)
        for i in range(2, max_c + 1):
            ops[i] = 1 + ops[bin(i).count('1')]
        allowed = [False] * (max_c + 1)
        limit = k - 1
        for c in range(1, max_c + 1):
            if ops[c] <= limit:
                allowed[c] = True
        from functools import lru_cache
        @lru_cache(None)
        def dp(pos, tight, cnt):
            if cnt > max_c:
                return 0
            if pos == L:
                return 1 if allowed[cnt] else 0
            res = 0
            up = int(s[pos]) if tight else 1
            for dig in range(up + 1):
                new_tight = tight and (dig == up)
                res = (res + dp(pos + 1, new_tight, cnt + dig)) % MOD
            return res
        total = dp(0, True, 0)
        pc_n = s.count('1')
        if allowed[pc_n]:
            total = (total - 1) % MOD
        return total

