def get_dist(M, start, goal):
    if start == goal:
        return 0
    q = collections.deque([(start, 0)])
    vis = set([start])
    while q:
        (x, y), d = q.popleft()
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = (x+dx)%M, (y+dy)%M
            if nx != ny and (nx,ny) not in vis:
                if (nx,ny) == goal:
                    return d+1
                vis.add((nx,ny))
                q.append(((nx,ny), d+1))
    return -1

