    M = int(data[1])
    A = [[0]*N for _ in range(N)]
    idx = 2
    for _ in range(M):
        u = int(data[idx])-1
        v = int(data[idx+1])-1
        idx += 2
        A[u][v] = A[v][u] = 1

    mat = [row[:] for row in A]
    where = [-1]*N
    row = 0
    for col in range(N):
        sel = -1
        for i in range(row, N):
            if mat[i][col]:
                sel = i
                break
        if sel == -1:
            continue
        mat[row], mat[sel] = mat[sel], mat[row]
        where[col] = row
        for i in range(N):
            if i != row and mat[i][col]:
                for j in range(N):
                    mat[i][j] ^= mat[row][j]
        row += 1
        if row == N:
            break

    basis = []
    for free in range(N):
        if where[free] == -1:
            vec = [0]*N
            vec[free] = 1
            for col in range(N):
                if where[col] != -1:
                    r = where[col]
                    vec[col] = mat[r][free]
            basis.append(vec)

    covered = [False]*N
    for vec in basis:
        for i in range(N):
            if vec[i]:
                covered[i] = True
    if not all(covered):
        print("No")
        return

    X = [0]*N
    for b, vec in enumerate(basis):
        for i in range(N):
            if vec[i]:
                X[i] |= (1 << b)
    print("Yes")
    print(" ".join(map(str, X)))

