import bisect
import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    Q = int(data[1])
    S = data[2]
    pos1 = []
    pos2 = []
    pos_slash = []
    for i, c in enumerate(S):
        if c == ord('1'):
            pos1.append(i + 1)
        elif c == ord('2'):
            pos2.append(i + 1)
        elif c == ord('/'):
            pos_slash.append(i + 1)

    def can(k, L, R):
        if k == 0:
            i = bisect.bisect_left(pos_slash, L)
            return i < len(pos_slash) and pos_slash[i] <= R
        j = bisect.bisect_left(pos1, L)
        if j + k - 1 >= len(pos1) or pos1[j + k - 1] > R:
            return False
        p_min = pos1[j + k - 1] + 1
        idx = bisect.bisect_right(pos2, R) - 1
        if idx < k - 1 or pos2[idx - k + 1] < L:
            return False
        p_max = pos2[idx - k + 1] - 1
        low = p_min if p_min > L else L
        high = p_max if p_max < R else R
        if low > high:
            return False
        i = bisect.bisect_left(pos_slash, low)
        return i < len(pos_slash) and pos_slash[i] <= high

    out_lines = []
    p = 3
    for _ in range(Q):
        L = int(data[p])
        R = int(data[p + 1])
        p += 2
        lo = 0
        hi = (R - L + 1) // 2
        ans_k = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid, L, R):
                ans_k = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if ans_k >= 0:
            out_lines.append(str(2 * ans_k + 1))
        else:
            out_lines.append('0')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()

