def test(N, trials=100):
    for _ in range(trials):
        P = list(range(1,N+1))
        Q = list(range(1,N+1))
        random.shuffle(P)
        random.shuffle(Q)
        R = [0]*N
        for k,p in enumerate(P):
            R[p-1]=k
        C = [0]*N
        for k,q in enumerate(Q):
            C[q-1]=k
        grid = [['0']*N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                grid[i][j] = '0' if R[i] + C[j] < N-1 else '1'
        if not check(grid, P, Q):
            return False, P, Q, grid
    return True, None, None, None

