import sys
from typing import List

sys.setrecursionlimit(10000)

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        turn_to = [1, 2, 3, 0]
        memo = {}

        def dfs(i, j, d, turned, expect):
            key = (i, j, d, turned, expect)
            if key in memo:
                return memo[key]
            res = 1
            next_expect = 0 if expect == 2 else 2
            # straight
            di, dj = dirs[d]
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == next_expect:
                res = max(res, 1 + dfs(ni, nj, d, turned, next_expect))
            # turn if not yet
            if not turned:
                nd = turn_to[d]
                di, dj = dirs[nd]
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == next_expect:
                    res = max(res, 1 + dfs(ni, nj, nd, True, next_expect))
            memo[key] = res
            return res

        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d in range(4):
                        ans = max(ans, dfs(i, j, d, False, 1))
        return ans

