from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count(req_parity, ro, re):
            m = ro + re
            if m == 0:
                return 1
            if req_parity == 1:  # odd
                needed_o = (m + 1) // 2
                needed_e = m // 2
            else:
                needed_e = (m + 1) // 2
                needed_o = m // 2
            if ro == needed_o and re == needed_e:
                return fact[ro] * fact[re]
            return 0

        used = [False] * (n + 1)
        result = []
        prev_parity = -1

        for _ in range(n):
            found = False
            for num in range(1, n + 1):
                if used[num]:
                    continue
                parity = num % 2
                if prev_parity != -1 and parity == prev_parity:
                    continue
                used[num] = True
                ro = re = 0
                for i in range(1, n + 1):
                    if not used[i]:
                        if i % 2:
                            ro += 1
                        else:
                            re += 1
                if ro + re == 0:
                    ways = 1
                else:
                    ways = count(1 - parity, ro, re)
                used[num] = False
                if ways < k:
                    k -= ways
                else:
                    result.append(num)
                    used[num] = True
                    prev_parity = parity
                    found = True
                    break
            if not found:
                return []
        return result

