class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n
        def modinv(x):
            return pow(x, MOD - 2, MOD)
        def binom(a, b):
            if b < 0 or b > a:
                return 0
            if b == 0 or b == a:
                return 1
            if b > a - b:
                b = a - b
            res = 1
            for i in range(b):
                res = res * (a - i) % MOD
                res = res * modinv(i + 1) % MOD
            return res
        pair_sum = m * n % MOD
        pair_sum = pair_sum * ((m + n) % MOD) % MOD
        pair_sum = pair_sum * ((N - 1) % MOD) % MOD
        pair_sum = pair_sum * modinv(6) % MOD
        ans = pair_sum * binom(N - 2, k - 2) % MOD
        return ans

