class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        pow10 = [0] * n
        pow10[0] = 1 % k
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % k
        coeff = [0] * m
        for j in range(m):
            c = pow10[n - 1 - j]
            if n - 1 - j != j:
                c = (c + pow10[j]) % k
            else:
                c %= k
            coeff[j] = c
        from_end = [[False] * k for _ in range(m + 1)]
        from_end[m][0] = True
        for j in range(m - 1, -1, -1):
