from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nge = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nge[i] = stack[-1]
            stack.append(i)

        LOG = 18
        nxt = [[n] * n for _ in range(LOG)]
        sum_add = [[0] * n for _ in range(LOG)]
        for i in range(n):
            nxt[0][i] = nge[i]
            sum_add[0][i] = nums[i] * (nge[i] - i)

        for kb in range(1, LOG):
            for i in range(n):
                mid = nxt[kb - 1][i]
                if mid >= n:
                    nxt[kb][i] = n
                    sum_add[kb][i] = sum_add[kb - 1][i]
                else:
                    nxt[kb][i] = nxt[kb - 1][mid]
                    sum_add[kb][i] = sum_add[kb - 1][i] + sum_add[kb - 1][mid]

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        def get_f(l: int, r: int) -> int:
            pos = l
            acc = 0
            for kb in range(LOG - 1, -1, -1):
                if nxt[kb][pos] <= r:
                    acc += sum_add[kb][pos]
                    pos = nxt[kb][pos]
            acc += nums[pos] * (r - pos + 1)
            return acc

        ans = 0
        L = 0
        for r in range(n):
            while L < r and get_f(L, r) - (prefix[r + 1] - prefix[L]) > k:
                L += 1
            ans += r - L + 1
        return ans

