        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    L = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(M)]
    C = [int(next(it)) for _ in range(L)]
    cards = A + B + C
    total = N + M + L
    # locations: 0 Takahashi, 1 Aoki, 2 table
    pow3 = [1] * total
    for i in range(1, total):
        pow3[i] = pow3[i - 1] * 3
    state0 = 0
    for i in range(M):
        state0 += 1 * pow3[N + i]
    for i in range(L):
        state0 += 2 * pow3[N + M + i]

    @lru_cache(maxsize=None)
    def wins(state, turn):
        s = state
        hand = []
        table = []
        for i in range(total):
            loc = s % 3
            if loc == turn:
                hand.append(i)
            elif loc == 2:
                table.append(i)
            s //= 3
        if not hand:
            return False
        for i in hand:
            ns = state + (2 - turn) * pow3[i]
            if not wins(ns, 1 - turn):
                return True
            val = cards[i]
            for j in table:
                if cards[j] < val:
                    ns2 = ns + (turn - 2) * pow3[j]
                    if not wins(ns2, 1 - turn):
                        return True
        return False

    print("Takahashi" if wins(state0, 0) else "Aoki")

