def has_hetero_matching(colors):
    # colors list of 0/1, equal number, check if exists non-crossing perfect matching all pairs different colors
    n = len(colors)
    # dp[i][j] whether subarray i to j-1 can be fully hetero matched, length even
    dp = [[False]*(n+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][i] = True  # empty
    for length in range(2, n+1, 2):
        for i in range(n-length+1):
            j = i + length
            # pair i with some k=i+1,i+3,..j-1, if colors differ, and inside and right ok
            for k in range(i+1, j, 2):
                if colors[i] != colors[k] and dp[i+1][k] and dp[k+1][j]:
                    dp[i][j] = True
                    break
    return dp[0][n]

