import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        star1 = p.find('*')
        star2 = p.find('*', star1 + 1)
        A = p[:star1]
        B = p[star1 + 1:star2]
        C = p[star2 + 1:]

        def kmp_occurrences(text, pattern):
            if not pattern:
                return list(range(len(text) + 1))
            m = len(pattern)
            pi = [0] * m
            k = 0
            for i in range(1, m):
                while k and pattern[k] != pattern[i]:
                    k = pi[k - 1]
                if pattern[k] == pattern[i]:
                    k += 1
                pi[i] = k
            res = []
            k = 0
            n = len(text)
            for i in range(n):
                while k and pattern[k] != text[i]:
                    k = pi[k - 1]
                if pattern[k] == text[i]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = pi[k - 1]
            return res

        posA = kmp_occurrences(s, A)
        posB = kmp_occurrences(s, B)
        posC = kmp_occurrences(s, C)
        lenA, lenB, lenC = len(A), len(B), len(C)
        ans = float('inf')
        for j in posB:
            limit = j - lenA
            idx = bisect.bisect_right(posA, limit) - 1
            if idx < 0:
                continue
            i = posA[idx]
            startk = j + lenB
            idxk = bisect.bisect_left(posC, startk)
            if idxk == len(posC):
                continue
            k = posC[idxk]
            ans = min(ans, k + lenC - i)
        return ans if ans != float('inf') else -1

