import itertools

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:2+N]))
    if K == 0:
        print(0)
        return
    total = 0
    for x in A:
        total ^= x
    M = min(K, N - K)
    if M == 0:
        print(total)
        return
    # We need max over subsets of size M of (xor if K==M else total ^ xor)
    use_exclude = (K > M)  # i.e. K > N-K, so excluding M
    best = 0
    for comb in itertools.combinations(A, M):
        s = 0
        for x in comb:
            s ^= x
        if use_exclude:
            val = total ^ s
        else:
            val = s
        if val > best:
            best = val
    print(best)

