def min_ops(pieces, targets, N):
    targets = set(targets)
    start = tuple(sorted(pieces))
    # BFS
    q = deque([(start, 0)])
    seen = {start}
    while q:
        pos, d = q.popleft()
        # check if occupied == targets
        occ = set(pos)
        if occ == targets:
            return d
        if d > 10: 
            continue
        for i in range(1, N+1):
            newpos = []
            for p in pos:
                if p < i:
                    newpos.append(p+1)
                elif p > i:
                    newpos.append(p-1)
                else:
                    newpos.append(p)
            nt = tuple(sorted(newpos))
            if nt not in seen:
                seen.add(nt)
                q.append((nt, d+1))
    return -1
