def min_moves(N, edges, S, T):
    adj = [[] for _ in range(N+1)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    # BFS state (posA, posB)
    start = (S, T)
    goal = (T, S)
    q = collections.deque([start])
    dist = {start: 0}
    while q:
        a,b = q.popleft()
        if (a,b) == goal:
            return dist[(a,b)]
        # move A
        for na in adj[a]:
            if na != b and (na, b) not in dist:
                dist[(na,b)] = dist[(a,b)] + 1
                q.append((na,b))
