        def gcd_lcm(arr):
            if not arr:
                return 0, 1
            g = arr[0]
            l = arr[0]
            for x in arr[1:]:
                g = math.gcd(g, x)
                l = l // math.gcd(l, x) * x
            return g, l

        n = len(nums)
        best = 0
        g, l = gcd_lcm(nums)
        best = max(best, g * l)
        for i in range(n):
            arr = nums[:i] + nums[i+1:]
            if not arr:
                score = 0
            else:
                g, l = gcd_lcm(arr)
                score = g * l
            best = max(best, score)
        return best

