import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    g = [[] for _ in range(N + 1)]
    rg = [[] for _ in range(N + 1)]
    for _ in range(M):
        a, b = map(int, input().split())
        g[a].append(b)
        rg[b].append(a)

    def bfs(start, graph):
        dist = [-1] * (N + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            du = dist[u]
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = du + 1
                    q.append(v)
        return dist

    d = bfs(1, g)
    rd = bfs(1, rg)
    ans = float('inf')
    for v in range(2, N + 1):
        if d[v] != -1 and rd[v] != -1:
            s = d[v] + rd[v]
            if s < ans:
                ans = s
    if ans == float('inf'):
        print(-1)
    else:
        print(ans)

if __name__ == '__main__':
    main()

