import itertools
import random

def brute(nums):
    n = len(nums)
    if n == 1:
        return 0
    # all subsets of intermediate points
    max_score = 0
    for r in range(n-1):
        for inter in itertools.combinations(range(1, n-1), r):
            path = [0] + list(inter) + [n-1]
            score = 0
            for a, b in zip(path, path[1:]):
                score += (b - a) * nums[a]
            if score > max_score:
                max_score = score
    return max_score

def greedy(nums):
    n = len(nums)
    current = 0
    score = 0
    for i in range(1, n):
        if nums[i] > nums[current]:
            score += (i - current) * nums[current]
            current = i
    score += (n - 1 - current) * nums[current]
    return score

def check(nums):
    b = brute(nums)
    g = greedy(nums)
    if b != g:
        return False, b, g
    return True, b, g

