        n = len(nums)
        if all(x == 0 for x in nums):
            return 0
        possible = [1] * n  # bit 0 set
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                possible[i] |= possible[i] << val
            if all((possible[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1

