import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            i = 3
            while i * i <= x:
                if x % i == 0:
                    return False
                i += 2
            return True

        if is_prime(n) or is_prime(m):
            return -1
        if n == m:
            return n

        d = len(str(n))
        INF = 10**18
        dist = {n: n}
        pq = [(n, n)]

        while pq:
            cost, cur = heapq.heappop(pq)
            if cost != dist.get(cur, INF):
                continue
            if cur == m:
                return cost
            scur = list(str(cur))
            for i in range(d):
                orig = int(scur[i])
                for delta in (-1, 1):
                    ndig = orig + delta
                    if ndig < 0 or ndig > 9:
                        continue
                    if i == 0 and ndig == 0 and d > 1:
                        continue
                    scur[i] = str(ndig)
                    nxt = int(''.join(scur))
                    scur[i] = str(orig)
                    if is_prime(nxt):
                        continue
                    ncost = cost + nxt
                    if ncost < dist.get(nxt, INF):
                        dist[nxt] = ncost
                        heapq.heappush(pq, (ncost, nxt))
        return -1

