        if n < 3:
            return 0
        s = ''.join(chr(x + 1) for x in nums)
        ans = 0
        for i in range(1, n - 1):
            if 2 * i < n and s[:i] == s[i:2 * i]:
                ans += n - 2 * i
                for j in range(i + 1, 2 * i):
                    L = j - i
                    if j + L <= n and s[i:j] == s[j:j + L]:
                        ans += 1
            else:
                maxL = (n - i) // 2
                for L in range(1, maxL + 1):
                    j = i + L
                    if s[i:j] == s[j:j + L]:
                        ans += 1
        return ans

