def can_one_edit(S, T):
    ls, lt = len(S), len(T)
    if abs(ls - lt) > 1:
        return False
    if ls == lt:
        diff = 0
        for a, b in zip(S, T):
            if a != b:
                diff += 1
                if diff > 1:
                    return False
        return True
    if ls < lt:
        S, T = T, S
        ls, lt = lt, ls
    # S is longer by 1
    i = j = 0
    while i < ls and j < lt and S[i] == T[j]:
        i += 1
        j += 1
    if j == lt:
        return ls - i == 1
    i += 1
    while i < ls and j < lt and S[i] == T[j]:
        i += 1
        j += 1
    return i == ls and j == lt

def main():
    K = int(input())
    S = input().strip()
    T = input().strip()
    print("Yes" if can_one_edit(S, T) else "No")

main()

