from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for t in targetIndices:
            is_target[t] = True
        INF = 10**9
        dp = [INF] * (m + 1)
        dp[0] = 0
        for i in range(n):
            cost = 1 if is_target[i] else 0
            for j in range(m - 1, -1, -1):
                if dp[j] < INF and source[i] == pattern[j]:
                    if dp[j] + cost < dp[j + 1]:
                        dp[j + 1] = dp[j] + cost
        return len(targetIndices) - dp[m]

