from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        def can(max_w: int) -> bool:
            rev = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= max_w:
                    rev[b].append(a)
            visited = [False] * n
            q = deque([0])
            visited[0] = True
            cnt = 1
            while q:
                u = q.popleft()
                for v in rev[u]:
                    if not visited[v]:
                        visited[v] = True
                        cnt += 1
                        q.append(v)
            return cnt == n

        lo, hi = 1, 10**6
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

