class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**18
        prev = [[INF] * 3 for _ in range(3)]
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    prev[c1][c2] = cost[0][c1] + cost[n - 1][c2]
        for j in range(1, m):
            curr = [[INF] * 3 for _ in range(3)]
            left = j
            right = n - 1 - j
            for pc1 in range(3):
                for pc2 in range(3):
                    base = prev[pc1][pc2]
                    if base >= INF:
                        continue
                    for c1 in range(3):
                        if c1 == pc1:
                            continue
                        add_left = cost[left][c1]
                        for c2 in range(3):
                            if c2 == pc2 or c1 == c2:
                                continue
                            val = base + add_left + cost[right][c2]
                            if val < curr[c1][c2]:
                                curr[c1][c2] = val
            prev = curr
        ans = INF
        for c1 in range(3):
            for c2 in range(3):
                if prev[c1][c2] < ans:
                    ans = prev[c1][c2]
        return ans

