def minCost(n, cost):
    m = n // 2
    # colors 0,1,2
    INF = float('inf')
    # dp[prev_c1][prev_c2] but since only 6, we can use dict or just iterate
    # Let's keep min cost for each possible (c1, c2) of current pair
    prev = [[INF]*3 for _ in range(3)]
    # init for pair 0
    for c1 in range(3):
        for c2 in range(3):
            if c1 != c2:
                prev[c1][c2] = cost[0][c1] + cost[n-1][c2]
    for j in range(1, m):
        curr = [[INF]*3 for _ in range(3)]
        house_left = j
        house_right = n-1-j
        for pc1 in range(3):
            for pc2 in range(3):
                if prev[pc1][pc2] == INF: continue
                for c1 in range(3):
                    if c1 == pc1: continue
                    for c2 in range(3):
                        if c2 == pc2 or c1 == c2: continue
                        curr[c1][c2] = min(curr[c1][c2], prev[pc1][pc2] + cost[house_left][c1] + cost[house_right][c2])
        prev = curr
    ans = min(prev[c1][c2] for c1 in range(3) for c2 in range(3))
    return ans

