class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        vowels = set('aeiou')
        count = 0
        for i in range(n):
            vowel_set = set()
            cons = 0
            for j in range(i, n):
                c = word[j]
                if c in vowels:
                    vowel_set.add(c)
                else:
                    cons += 1
                if cons > k:
                    break
                if cons == k and len(vowel_set) == 5:
                    count += 1
        return count

